/bin/bash -lc "python3 - <<'PY'
import os,socket,urllib.request
print('API key present:',bool(os.environ.get('ASSEMBLYAI_API_KEY')))
print('Proxy settings:',urllib.request.getproxies())
for host in ['api.assemblyai.com','www.assemblyai.com','assemblyai.com','raw.githubusercontent.com','pypi.org']:
 try: print(host,socket.gethostbyname_ex(host))
 except OSError as e: print(host,e)
for url in ['https://api.assemblyai.com/v2/transcript?limit=1','https://assemblyai.com/docs/api-reference/transcripts/submit']:
 try:
  req=urllib.request.Request(url,headers={'authorization':os.environ.get('ASSEMBLYAI_API_KEY','')}) if 'api.assemblyai.com' in url else urllib.request.Request(url)
  r=urllib.request.urlopen(req,timeout=20)
  print(url,r.status,r.read(2000).decode())
 except Exception as e: print(url,type(e).__name__,str(e))
PY"

